/**
 * dsh-market — host half.
 *
 * A plugin market needs something the harness deliberately does not have: a
 * catalogue. The plugin manager installs by *spec* (npm name, GitHub repo, local
 * path) and only knows what is already installed; the npm "registry" module is
 * about which registry to ask, not about which plugins exist. So this half
 * builds the catalogue from the two honest sources:
 *
 *   * **official** — the plugin bundles that ship inside this dsh installation
 *     (`<install>/node_modules/@deepseek-ai/*` with `dsh.bundle.patch`). These
 *     are the packages the deployment already trusts, and installing one is a
 *     name, so it is one click.
 *   * **online** — npm's search API, asked with a keyword (default
 *     `keywords:dsh-plugin`), cached, and reported with a readable error string
 *     when the network cannot be reached.
 *
 * It serves both over one authenticated same-origin route, so the client half
 * needs no Remote namespace of its own and cannot be reached from outside the
 * composition's origin fence:
 *
 *   GET /dsh-market/catalog   → { official, online, installed, errors, generatedAt }
 *
 * The catalogue is read-only. Every mutation — install, enable, disable, remove —
 * goes through `@deepseek-ai/dsh-plugin-manager`'s own Remote API from the client
 * half; nothing here writes profile files.
 */

import { readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';

/** Loader row id, for diagnostics. */
export const name = 'dsh-market';

/** The composition's HTTP server and its authenticated-request fence. */
export const inject = ['webServer', 'connection'];

/** Catalogue route path. */
export const CATALOG_PATH = '/dsh-market/catalog';

/** Where the catalogue is built from; both are read-only inputs. */
const DEFAULTS = {
    /** Ask npm for a catalogue too. */
    online: true,
    /** Registry root; empty means npm's own. */
    registry: '',
    /** npm search query for the online half. */
    searchText: 'keywords:dsh-plugin',
    /** How many online hits to ask for. */
    searchSize: 25,
    /** How long a built catalogue is reused. */
    cacheMs: 600000,
    /** Bound on the npm request. */
    timeoutMs: 8000,
    /** Override the dsh installation root (tests, exotic deployments). */
    install: '',
    /** Override the profile directory whose bundles are read. */
    profile: '',
};

/** The composition's connection service (its package type is not a Host dependency here). */
function connectionOf(ctx) {
    return Reflect.get(ctx, 'connection');
}

/** Answer an untrusted/unauthenticated request; true when it was rejected. */
function rejected(ctx, req, res) {
    const rejection = connectionOf(ctx)?.requestRejection(req);
    if (rejection === undefined || rejection === null) return false;
    res.statusCode = rejection;
    res.end();
    return true;
}

/** The dsh installation root: what ships with the app. */
export function installRoot(env = process.env) {
    return env.DSH_INSTALL || '/opt/dsh';
}

/** The profile directory whose `dsh.profile.bundles` says what is installed. */
export function profileRoot(env = process.env) {
    return env.DSH_PROFILE_DIR || '';
}

/**
 * The profile this Host process actually mounted.
 *
 * `DSH_PROFILE_DIR` is inherited from whatever launched the process, so a second
 * instance started from a session shell can see another profile's directory —
 * a real bug this deployment hit (a throwaway instance listed the live
 * profile's bundles). `profileContext` is the directory the Loader composed,
 * which is the only answer that always matches the running plugin set.
 *
 * @param ctx - Host context that may carry the profile context.
 * @returns the mounted profile directory, or '' when there is none.
 */
export function mountedProfile(ctx) {
    try {
        const profile = Reflect.get(ctx, 'profileContext');
        return typeof profile?.dir === 'string' ? profile.dir : '';
    } catch {
        return '';
    }
}

/** One localised text field out of a package manifest's `meta`. */
function textOf(value, fallback) {
    if (typeof value === 'string' && value.length > 0) return value;
    if (value !== null && typeof value === 'object') {
        for (const candidate of [value.zh, value.en, ...Object.values(value)]) {
            if (typeof candidate === 'string' && candidate.length > 0) return candidate;
        }
    }
    return fallback;
}

/** The bundle names the profile currently selects. */
export async function installedBundles(profile, read = readFile) {
    if (!profile) return [];
    try {
        const manifest = JSON.parse(await read(join(profile, 'package.json'), 'utf8'));
        const bundles = manifest?.dsh?.profile?.bundles;
        return Array.isArray(bundles) ? bundles.filter((item) => typeof item === 'string') : [];
    } catch {
        return [];
    }
}

/**
 * Every bundle that ships inside this dsh installation.
 *
 * A package is one-click installable exactly when it carries `dsh.bundle.patch`:
 * its patch is what contributes the Loader rows, so naming it is enough. Plain
 * plugin packages (no patch) are deliberately left out — installing one would
 * not enable anything.
 *
 * @param install - dsh installation root.
 * @param installed - bundle names already selected by the profile.
 * @param deps - injectable filesystem for tests.
 * @returns catalogue entries, sorted by name.
 */
export async function officialCatalog(install, installed = [], deps = {}) {
    const readDir = deps.readdir ?? readdir;
    const read = deps.readFile ?? readFile;
    const root = join(install, 'node_modules', '@deepseek-ai');
    const names = await readDir(root).catch(() => []);
    const selected = new Set(installed);
    const out = [];
    for (const entry of names) {
        let manifest;
        try {
            manifest = JSON.parse(await read(join(root, entry, 'package.json'), 'utf8'));
        } catch {
            continue; // not a package, or unreadable: not a candidate
        }
        if (typeof manifest?.dsh?.bundle?.patch !== 'string') continue;
        const packageName = typeof manifest.name === 'string' ? manifest.name : `@deepseek-ai/${entry}`;
        out.push({
            name: packageName,
            version: typeof manifest.version === 'string' ? manifest.version : '',
            title: textOf(manifest?.meta?.title, ''),
            description: textOf(manifest?.meta?.description, typeof manifest.description === 'string' ? manifest.description : ''),
            source: 'official',
            installed: selected.has(packageName),
        });
    }
    return out.sort((left, right) => left.name.localeCompare(right.name));
}

/** npm's own registry root. */
export const OFFICIAL_REGISTRY = 'https://registry.npmjs.org/';

/**
 * The online half: npm's search API.
 *
 * npm's registry is a real catalogue with a real search endpoint, and a plugin
 * published for dsh is discoverable by keyword. A failure here is reported, not
 * thrown: the market must still show the official half when the phone is
 * offline or behind a VPN that cannot reach the registry.
 *
 * @param options - registry, query, size, timeout, and an injectable fetch.
 * @returns online catalogue entries.
 * @throws when the registry answers with an error or a malformed body.
 */
/** One readable line for a failed registry request, cause included. */
export function describeFailure(error) {
    const message = error instanceof Error ? error.message : String(error);
    const code = error?.cause?.code ?? error?.cause?.errno ?? error?.code;
    return typeof code === 'string' && code.length > 0 && !message.includes(code) ? `${message} (${code})` : message;
}

export async function onlineCatalog(options = {}) {
    const fetchImpl = options.fetch ?? fetch;
    const base = (options.registry || OFFICIAL_REGISTRY).replace(/\/+$/u, '');
    const query = options.searchText ?? DEFAULTS.searchText;
    const size = options.searchSize ?? DEFAULTS.searchSize;
    const url = `${base}/-/v1/search?text=${encodeURIComponent(query)}&size=${String(size)}`;
    const attempts = Math.max(1, options.attempts ?? 2);
    let body;
    for (let attempt = 1; ; attempt += 1) {
        try {
            const response = await fetchImpl(url, {
                headers: { accept: 'application/json' },
                signal: AbortSignal.timeout(options.timeoutMs ?? DEFAULTS.timeoutMs),
            });
            // A 5xx is as transient as a dropped connection on mobile data.
            if (!response.ok && response.status < 500) throw new Error(`registry HTTP ${String(response.status)}`);
            if (!response.ok) throw Object.assign(new Error(`registry HTTP ${String(response.status)}`), { retryable: true });
            body = await response.json();
            break;
        } catch (error) {
            const retryable = error?.retryable === true || error?.name === 'TimeoutError' || error?.name === 'AbortError' || error?.cause !== undefined || /fetch failed|network|socket|ECONN|EAI_/iu.test(String(error?.message ?? ''));
            if (attempt >= attempts || !retryable) throw new Error(describeFailure(error));
            await new Promise((resolve) => setTimeout(resolve, 400));
        }
    }
    const objects = Array.isArray(body?.objects) ? body.objects : [];
    return objects.map((object) => ({
        name: typeof object?.package?.name === 'string' ? object.package.name : '',
        version: typeof object?.package?.version === 'string' ? object.package.version : '',
        description: typeof object?.package?.description === 'string' ? object.package.description : '',
        publisher: typeof object?.package?.publisher?.username === 'string' ? object.package.publisher.username : '',
        date: typeof object?.package?.date === 'string' ? object.package.date : '',
        link: typeof object?.package?.links?.npm === 'string' ? object.package.links.npm : '',
        source: 'npm',
    })).filter((entry) => entry.name !== '');
}

/**
 * Build the whole catalogue, with a cache and a per-source error string.
 *
 * @param config - row config (see DEFAULTS).
 * @param deps - injectable environment and I/O for tests.
 * @returns the catalogue document served on {@link CATALOG_PATH}.
 */
export function createCatalog(config = {}, deps = {}) {
    const cfg = { ...DEFAULTS, ...config };
    const readDir = deps.readdir ?? readdir;
    const read = deps.readFile ?? readFile;
    const now = deps.now ?? (() => Date.now());
    const env = deps.env ?? process.env;
    let cached = null;
    let cachedAt = 0;
    let inflight = null;

    async function build() {
        const install = deps.install || cfg.install || installRoot(env);
        const profile = deps.profile || cfg.profile || profileRoot(env);
        const errors = {};
        const installed = await installedBundles(profile, read);
        const official = await officialCatalog(install, installed, { readdir: readDir, readFile: read }).catch((error) => {
            errors.official = error instanceof Error ? error.message : String(error);
            return [];
        });
        let online = [];
        if (cfg.online) {
            try {
                online = await onlineCatalog({
                    registry: cfg.registry,
                    searchText: cfg.searchText,
                    searchSize: cfg.searchSize,
                    timeoutMs: cfg.timeoutMs,
                    fetch: deps.fetch,
                });
            } catch (error) {
                errors.online = error instanceof Error ? error.message : String(error);
            }
        }
        return { official, online, installed, errors, generatedAt: now() };
    }

    /**
     * The catalogue document, rebuilt at most once per `cacheMs`.
     * @param force - ignore the cache (the page's refresh button).
     */
    return async function catalog(force = false) {
        if (!force && cached !== null && now() - cachedAt < cfg.cacheMs) return { ...cached, cached: true };
        if (inflight !== null) return inflight;
        inflight = build().then((document) => {
            cached = document;
            cachedAt = now();
            inflight = null;
            return { ...document, cached: false };
        }).catch((error) => {
            inflight = null;
            throw error;
        });
        return inflight;
    };
}

/**
 * Register the catalogue route for this plugin's lifetime.
 * @param ctx - Host context carrying the webserver and the connection fence.
 * @param config - this row's config.
 */
export function apply(ctx, config = {}) {
    // The mounted profile wins over the inherited env var: see mountedProfile().
    const catalog = createCatalog(config ?? {}, { profile: config?.profile || mountedProfile(ctx) });
    ctx.effect(() => ctx.webServer.register({
        kind: 'exact',
        path: CATALOG_PATH,
        handler: async (req, res) => {
            if (rejected(ctx, req, res)) return;
            if (req.method !== 'GET') {
                res.statusCode = 405;
                res.setHeader('allow', 'GET');
                res.end();
                return;
            }
            const refresh = /[?&]refresh=1/.test(req.url ?? '');
            try {
                const document = await catalog(refresh);
                res.statusCode = 200;
                res.setHeader('content-type', 'application/json; charset=utf-8');
                res.setHeader('cache-control', 'no-store');
                res.end(JSON.stringify(document));
            } catch (error) {
                // The page shows this verbatim, so it must be a sentence a person
                // can act on, never a stack trace.
                res.statusCode = 200;
                res.setHeader('content-type', 'application/json; charset=utf-8');
                res.setHeader('cache-control', 'no-store');
                res.end(JSON.stringify({
                    official: [],
                    online: [],
                    installed: [],
                    errors: { catalog: `目录读取失败：${error instanceof Error ? error.message : String(error)}` },
                    generatedAt: Date.now(),
                }));
            }
        },
    }), `dsh-market: GET ${CATALOG_PATH}`);
}
